  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

/* Tournament Cards */
.tournament-card {
  background: var(--card-bg);
  border-radius: 1rem;
  overflow: hidden;
  transition: all 0.3s ease;
  border: 2px solid transparent;
  cursor: pointer;
}

.tournament-card:hover {
  border-color: var(--primary-gold);
  transform: translateY(-8px);
  box-shadow: 0 0 30px rgba(255, 215, 0, 0.3);
}

.tournament-card-header {
  background: linear-gradient(135deg, rgba(255, 215, 0, 0.2), rgba(255, 140, 0, 0.2));
  padding: 1.5rem;
  border-bottom: 2px solid var(--primary-gold);
}

.tournament-name {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--primary-gold);
  margin-bottom: 0.5rem;
}

.tournament-type {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.tournament-card-body {
  padding: 1.5rem;
}

.tournament-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
}

.tournament-status {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  border-radius: 1rem;
  font-size: 0.75rem;
  font-weight: 600;
}

.status-registration {
  background: var(--success-green);
  color: white;
}

.status-ongoing {
  background: var(--accent-orange);
  color: white;
}

.status-completed {
  background: var(--text-muted);
  color: white;
}

/* Standings Table */
.standings-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  margin: 1rem 0;
}

.standings-table thead {
  background: rgba(255, 215, 0, 0.1);
  position: sticky;
  top: 0;
}

.standings-table th {
  padding: 1rem;
  text-align: left;
  color: var(--primary-gold);
  font-weight: 600;
  border-bottom: 2px solid var(--primary-gold);
}

.standings-table td {
  padding: 1rem;
  border-bottom: 1px solid var(--border-color);
  transition: all 0.3s ease;
}

.standings-table tr {
  transition: all 0.3s ease;
}

.standings-table tbody tr:hover {
  background: rgba(255, 215, 0, 0.05);
  transform: scale(1.01);
}

.position-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  font-weight: bold;
  background: var(--card-bg);
  border: 2px solid var(--border-color);
}

.position-1 { background: linear-gradient(135deg, #FFD700, #FFA500); color: #000; }
.position-2 { background: linear-gradient(135deg, #C0C0C0, #A8A8A8); color: #000; }
.position-3 { background: linear-gradient(135deg, #CD7F32, #A0522D); color: #fff; }

.team-name-cell {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.team-logo {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--primary-gold);
}

.team-name-link {
  color: var(--text-light);
  text-decoration: none;
  font-weight: 600;
  transition: all 0.3s ease;
}

.team-name-link:hover {
  color: var(--primary-gold);
  text-decoration: underline;
}

.form-indicator {
  display: flex;
  gap: 0.25rem;
}

.form-badge {
  width: 1.25rem;
  height: 1.25rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: bold;
}

.form-w { background: var(--success-green); color: white; }
.form-d { background: var(--text-muted); color: white; }
.form-l { background: var(--danger-red); color: white; }

/* Match Cards */
.match-card {
  background: var(--card-bg);
  border-radius: 1rem;
  padding: 1.5rem;
  border: 1px solid var(--border-color);
  transition: all 0.3s ease;
}

.match-card:hover {
  border-color: var(--primary-gold);
  box-shadow: var(--shadow-glow);
}

.match-teams {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1rem;
}

.match-team {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  flex: 1;
}

.match-team-name {
  font-weight: 600;
  text-align: center;
}

.match-vs {
  color: var(--text-muted);
  font-weight: bold;
  font-size: 1.25rem;
}

.match-score {
  font-size: 2rem;
  font-weight: bold;
  color: var(--primary-gold);
}

.match-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 1rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border-color);
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* Forms */
.form-group {
  margin-bottom: 1.5rem;
}

.form-label {
  display: block;
  margin-bottom: 0.5rem;
  color: var(--text-light);
  font-weight: 500;
}

.form-control {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 2px solid var(--border-color);
  border-radius: 0.5rem;
  background: var(--dark-bg);
  color: var(--text-light);
  font-size: 1rem;
  transition: all 0.3s ease;
}

.form-control:focus {
  outline: none;
  border-color: var(--primary-gold);
  box-shadow: 0 0 0 3px rgba(255, 215, 0, 0.1);
}

textarea.form-control {
  resize: vertical;
  min-height: 100px;
}

.form-help {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.form-error {
  color: var(--danger-red);
  font-size: 0.875rem;
  margin-top: 0.25rem;
}

/* Badges & Achievements */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: 2rem;
  font-size: 0.875rem;
  font-weight: 600;
}

.badge-gold {
  background: linear-gradient(135deg, var(--primary-gold), var(--gold-dark));
  color: var(--dark-bg);
}

.badge-silver {
  background: linear-gradient(135deg, #C0C0C0, #A8A8A8);
  color: var(--dark-bg);
}

.badge-bronze {
  background: linear-gradient(135deg, #CD7F32, #A0522D);
  color: white;
}

/* Utility Classes */
.text-center { text-align: center; }
.text-right { text-align: right; }
.text-muted { color: var(--text-muted); }
.text-gold { color: var(--primary-gold); }
.text-success { color: var(--success-green); }
.text-danger { color: var(--danger-red); }

.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }

.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }

.p-2 { padding: 1rem; }
.p-3 { padding: 1.5rem; }
.p-4 { padding: 2rem; }

/* Responsive */
@media (max-width: 768px) {
  .navbar-container {
    position: relative;
  }

  .navbar-menu {
    display: none;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--card-bg);
    padding: 1rem;
    border-bottom: 2px solid var(--primary-gold);
    box-shadow: var(--shadow-xl);
    z-index: 999;
  }

  .navbar-menu.active {
    display: flex !important;
  }

  .navbar-toggle {
    display: block !important;
    background: none;
    border: none;
    color: var(--primary-gold);
    font-size: 1.75rem;
    cursor: pointer;
    padding: 0.5rem;
  }

  .navbar-menu li {
    width: 100%;
  }

  .navbar-link {
    display: block;
    width: 100%;
    text-align: center;
    padding: 0.75rem;
  }

  .hero-title {
    font-size: 2rem;
  }

  .hero-stats {
    gap: 1.5rem;
  }

  .grid-2, .grid-3, .grid-4 {
    grid-template-columns: 1fr;
  }
}

/* Loading States */
.loading {
  display: inline-block;
  width: 2rem;
  height: 2rem;
  border: 3px solid rgba(255, 215, 0, 0.2);
  border-top-color: var(--primary-gold);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Messages/Alerts */
.alert {
  padding: 1rem 1.5rem;
  border-radius: 0.5rem;
  margin-bottom: 1rem;
  border-left: 4px solid;
}

.alert-success {
  background: rgba(16, 185, 129, 0.1);
  border-color: var(--success-green);
  color: var(--success-green);
}

.alert-error {
  background: rgba(239, 68, 68, 0.1);
  border-color: var(--danger-red);
  color: var(--danger-red);
}

.alert-info {
  background: rgba(255, 215, 0, 0.1);
  border-color: var(--primary-gold);
  color: var(--primary-gold);
}

